"""Regenerate evaluation.json from the frozen question set."""
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import bench  # noqa: E402

# Frozen domain aggregation weights. Each entry maps item_id -> weight; the domain
# score is the weighted mean of the observed item grades in [0,1].
WEIGHTS = json.load(open(os.path.join(HERE, "assets", "domain_weights.json"))) \
    if os.path.exists(os.path.join(HERE, "assets", "domain_weights.json")) else None


def main(subset=None, out=None):
    items = bench.build_all()
    if subset:
        items = [i for i in items if i["id"] in subset]
    doms = {}
    for it in items:
        doms.setdefault(it["domain"], []).append(it["id"])

    if WEIGHTS:
        agg = {d: {"kind": "weighted_mean",
                   "weights": {k: v for k, v in WEIGHTS[d].items() if k in {i["id"] for i in items}}}
               for d in WEIGHTS}
    else:
        agg = {d: {"kind": "weighted_mean", "weights": {i: 1.0 for i in ids}}
               for d, ids in doms.items()}

    manifest = {
        "protocol_version": 1,
        "selection": "fixed",
        "questions": [{"id": i["question_id"], "prompt": i["prompt"]} for i in items],
        "items": [{"id": i["id"], "question_id": i["question_id"], "domain": i["domain"],
                   "family": i["family"], "weight": 1.0} for i in items],
        "aggregation": {"kind": "weighted_mean"},
        "domain_aggregations": agg,
    }
    path = out or os.path.join(HERE, "evaluation.json")
    with open(path, "w") as fh:
        json.dump(manifest, fh, indent=1)
    print(path, len(items), {d: len(v) for d, v in doms.items()})


if __name__ == "__main__":
    main()

"""Predicate helpers for programmatically verifiable instruction constraints."""
import json
import re


def words(t):
    return re.findall(r"[A-Za-z0-9'’-]+", t)


def lines(t):
    return [l for l in t.strip().splitlines()]


def nonempty_lines(t):
    return [l.strip() for l in t.strip().splitlines() if l.strip()]


def wc_between(lo, hi):
    return lambda t: lo <= len(words(t)) <= hi


def contains_all(*subs, ci=True):
    def f(t):
        s = t.lower() if ci else t
        return all((x.lower() if ci else x) in s for x in subs)
    return f


def contains_none(*subs, ci=True):
    def f(t):
        s = t.lower() if ci else t
        return not any((x.lower() if ci else x) in s for x in subs)
    return f


def no_word(*ws):
    def f(t):
        got = {w.lower() for w in words(t)}
        return not any(w.lower() in got for w in ws)
    return f


def rx(pattern, flags=0, count=None):
    p = re.compile(pattern, flags)
    def f(t):
        hits = p.findall(t)
        return len(hits) == count if count is not None else bool(hits)
    return f


def line_count(lo, hi=None):
    hi = lo if hi is None else hi
    return lambda t: lo <= len(nonempty_lines(t)) <= hi


def starts_with(pref):
    return lambda t: t.strip().startswith(pref)


def ends_with(suf):
    return lambda t: t.strip().rstrip().endswith(suf)


_ABBR = re.compile(r"\b(?:[A-Za-z]|a\.m|p\.m|e\.g|i\.e|etc|vs|Mr|Mrs|Ms|Dr|Prof|St|No|Fig|approx|Inc|Ltd|Co|U\.S|cf|al)\.$")


def sentences(t):
    """Split into sentences, ignoring boundaries created by common abbreviations."""
    parts = re.split(r"(?<=[.!?])\s+", t.strip())
    out = []
    for p in parts:
        if out and _ABBR.search(out[-1]):
            out[-1] = out[-1] + " " + p
        else:
            out.append(p)
    return [p for p in out if p.strip()]


def sentence_count(lo, hi):
    def f(t):
        return lo <= len(sentences(t)) <= hi
    return f


def bullets(marker, lo, hi=None):
    hi = lo if hi is None else hi
    def f(t):
        n = len([l for l in nonempty_lines(t) if l.startswith(marker)])
        return lo <= n <= hi
    return f


def json_obj(t):
    """Parse the largest JSON object/array in the reply."""
    m = re.findall(r"```(?:json)?\s*\n(.*?)```", t, re.S)
    cands = list(m) + [t]
    for c in cands:
        c = c.strip()
        for opener, closer in (("{", "}"), ("[", "]")):
            i, j = c.find(opener), c.rfind(closer)
            if i >= 0 and j > i:
                try:
                    return json.loads(c[i:j + 1])
                except Exception:
                    pass
    return None


def json_check(fn):
    def f(t):
        obj = json_obj(t)
        return obj is not None and bool(fn(obj))
    return f


def md_table(t):
    """Return list of row-cell-lists for the first pipe table found."""
    rows = []
    for l in nonempty_lines(t):
        if l.startswith("|") and l.count("|") >= 2:
            cells = [c.strip() for c in l.strip().strip("|").split("|")]
            if all(re.fullmatch(r":?-{2,}:?", c) for c in cells):
                continue
            rows.append(cells)
        elif rows:
            break
    return rows


def table_check(fn):
    def f(t):
        rows = md_table(t)
        return bool(rows) and bool(fn(rows))
    return f


def nums_in(t):
    return [float(x.replace(",", "")) for x in
            re.findall(r"-?\d[\d,]*\.?\d*", t.replace("$", ""))]


def has_number(target, tol=0.005, rel=False):
    def f(t):
        for v in nums_in(t):
            d = abs(v - target)
            if (d <= tol * max(1.0, abs(target))) if rel else (d <= tol):
                return True
        return False
    return f


def all_lines_match(pattern):
    p = re.compile(pattern)
    return lambda t: bool(nonempty_lines(t)) and all(p.match(l) for l in nonempty_lines(t))


def first_letters_spell(word):
    def f(t):
        ls = [l for l in nonempty_lines(t)]
        if len(ls) < len(word):
            return False
        got = "".join(l.lstrip("-*0123456789. ").strip()[:1].upper() for l in ls[:len(word)])
        return got == word.upper()
    return f


def each_line_wc(lo, hi):
    def f(t):
        ls = nonempty_lines(t)
        return bool(ls) and all(lo <= len(words(l)) <= hi for l in ls)
    return f


def no_markdown(t):
    return not re.search(r"(\*\*|^#|^\s*[-*]\s|```)", t, re.M)


def ordered_sections(*heads):
    def f(t):
        pos, last = [], -1
        for h in heads:
            i = t.lower().find(h.lower())
            if i < 0 or i <= last:
                return False
            last = i
            pos.append(i)
        return True
    return f


def unique_words_ratio(min_ratio):
    def f(t):
        w = [x.lower() for x in words(t)]
        return bool(w) and len(set(w)) / len(w) >= min_ratio
    return f

"""Deterministic local graders shared by every item family.

All graders take the candidate's raw reply text and return either a float in
[0,1] or a dict accepted by research_sdk.Client.item.  No grader inspects the
candidate identity, and none of them looks at reference-benchmark labels.
"""
import json
import os
import re
import subprocess
import sys
import tempfile

# ---------------------------------------------------------------- text utils

CODE_RE = re.compile(r"```(?:python|py)?\s*\n(.*?)```", re.S)


def extract_code(text):
    """Last fenced block wins; fall back to the whole reply."""
    blocks = CODE_RE.findall(text)
    if blocks:
        return max(blocks, key=len)
    return text


def extract_tagged(text, tag="ANSWER"):
    """Return the content after the final `TAG:` marker (or boxed{} / last line)."""
    pat = re.compile(r"(?:\*\*)?" + tag + r"(?:\*\*)?\s*[:\-]?\s*(.+)", re.I)
    hits = pat.findall(text)
    if hits:
        return hits[-1].strip()
    boxed = find_boxed(text)
    if boxed is not None:
        return boxed
    lines = [l.strip() for l in text.strip().splitlines() if l.strip()]
    return lines[-1] if lines else ""


def find_boxed(text):
    idx = text.rfind("\\boxed")
    if idx < 0:
        return None
    i = text.find("{", idx)
    if i < 0:
        return None
    depth, out = 0, []
    for ch in text[i:]:
        if ch == "{":
            depth += 1
            if depth == 1:
                continue
        elif ch == "}":
            depth -= 1
            if depth == 0:
                break
        out.append(ch)
    return "".join(out).strip()


_NORM_DROP = re.compile(r"[\s\$\\,]+")


def norm_answer(s):
    """Aggressive canonicalisation for short exact-match answers."""
    if s is None:
        return ""
    s = s.strip()
    s = re.sub(r"^\**|\**$", "", s).strip()
    s = s.replace("\\left", "").replace("\\right", "")
    s = s.replace("\\!", "").replace("\\;", "").replace("\\,", "")
    s = s.replace("\\dfrac", "\\frac").replace("\\tfrac", "\\frac")
    s = s.replace("^{\\circ}", "").replace("^\\circ", "")
    s = re.sub(r"\\text\{([^}]*)\}", r"\1", s)
    s = re.sub(r"\\mathbb\{([^}]*)\}", r"\1", s)
    s = re.sub(r"\\mathrm\{([^}]*)\}", r"\1", s)
    s = s.rstrip(".")
    s = s.lower()
    s = _NORM_DROP.sub("", s)
    s = s.replace("{", "").replace("}", "").replace("(", "").replace(")", "")
    return s


def numeric_value(s):
    s = s.replace(",", "").replace("$", "").strip()
    m = re.fullmatch(r"[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?%?", s)
    if not m:
        return None
    try:
        return float(s.rstrip("%"))
    except ValueError:
        return None


def exact_match(text, gold, aliases=(), tag="ANSWER"):
    got = extract_tagged(text, tag)
    cands = [gold, *aliases]
    g = norm_answer(got)
    if g == "":
        return {"score": 0.0, "answer_status": "invalid"}
    for c in cands:
        if g == norm_answer(c):
            return {"score": 1.0, "answer_status": "answered"}
    gv, = (numeric_value(got),)
    if gv is not None:
        for c in cands:
            cv = numeric_value(str(c))
            if cv is not None and abs(gv - cv) <= 1e-6 * max(1.0, abs(cv)):
                return {"score": 1.0, "answer_status": "answered"}
    return {"score": 0.0, "answer_status": "answered"}


def mc_match(text, gold):
    got = extract_tagged(text)
    m = re.search(r"\b([A-J])\b", got.upper())
    letter = m.group(1) if m else norm_answer(got).upper()[:1]
    return {"score": 1.0 if letter == gold.strip().upper()[:1] else 0.0,
            "answer_status": "answered" if letter else "invalid"}


# ------------------------------------------------------------- code sandbox

HARNESS = '''
import json, sys, math
RESULTS = {}
def _run(name, fn):
    try:
        fn()
        RESULTS[name] = 1
    except BaseException:
        RESULTS[name] = 0
try:
    exec(compile(open(sys.argv[1]).read(), "candidate.py", "exec"), globals())
except BaseException:
    print("__RESULTS__" + json.dumps({}))
    raise SystemExit(0)
{TESTS}
print("__RESULTS__" + json.dumps(RESULTS))
'''


def run_code_tests(code, tests, timeout=30):
    """tests: list of python snippets; each must raise on failure.

    Returns (fraction_passed, detail dict).  A candidate file that fails to
    import scores 0 on every test.
    """
    body = []
    for i, snip in enumerate(tests):
        indented = "\n".join("    " + l for l in snip.strip("\n").splitlines())
        body.append("def _t%d():\n%s\n_run('t%d', _t%d)" % (i, indented, i, i))
    prog = HARNESS.replace("{TESTS}", "\n".join(body))
    with tempfile.TemporaryDirectory() as d:
        cand = os.path.join(d, "candidate.py")
        harn = os.path.join(d, "harness.py")
        open(cand, "w").write(code)
        open(harn, "w").write(prog)
        try:
            p = subprocess.run([sys.executable, harn, cand], cwd=d, timeout=timeout,
                               capture_output=True, text=True)
            out = p.stdout
        except subprocess.TimeoutExpired:
            return 0.0, {"error": "timeout"}
        except Exception as exc:                      # pragma: no cover
            return 0.0, {"error": repr(exc)}
    m = re.search(r"__RESULTS__(\{.*\})", out)
    if not m:
        return 0.0, {"error": "no-results", "stdout": out[-400:]}
    res = json.loads(m.group(1))
    if not tests:
        return 0.0, {}
    return sum(res.get("t%d" % i, 0) for i in range(len(tests))) / len(tests), res


def code_grader(tests, timeout=30):
    def grade(text):
        code = extract_code(text)
        if not code.strip():
            return {"score": 0.0, "answer_status": "invalid"}
        frac, detail = run_code_tests(code, tests, timeout)
        return {"score": round(frac, 6), "answer_status": "answered", "detail": detail}
    return grade


# ------------------------------------------------- constraint-checklist grader

def checklist_grader(checks):
    """checks: list of (name, callable(text) -> bool).  Score = fraction true."""
    def grade(text):
        passed, names = 0, {}
        for name, fn in checks:
            try:
                ok = bool(fn(text))
            except Exception:
                ok = False
            names[name] = int(ok)
            passed += int(ok)
        return {"score": round(passed / len(checks), 6), "answer_status": "answered",
                "detail": names}
    return grade

"""Standard-library client for independently executed evaluation suites."""
import json
import os
import time
import urllib.request
import urllib.error
import uuid
import hashlib
import copy
from pathlib import Path


class EvaluationError(RuntimeError):
    def __init__(self,status,payload,headers):
        error=payload.get('error',{})
        self.category=error.get('type','request_error') if isinstance(error,dict) else 'request_error'
        self.details=payload
        self.status=status
        self.operation_id=headers.get('x-seb-operation-id')
        ident=headers.get('x-seb-request-id')
        self.evidence=[{'kind':'llm','id':ident}] if ident and status!=402 else []
        message=error.get('message','') if isinstance(error,dict) else str(error)
        super().__init__(f'HTTP {status}: {self.category}; operation={self.operation_id}; {message[:500]}')


class Client:
    def __init__(self, context=None):
        path=context or os.environ.get('SEB_CONTEXT','/workspace/access.json')
        self.context=json.loads(Path(path).read_text())
        self.resume=self.context.get('measurement_resume',{})
        self.completed_items=copy.deepcopy(self.resume.get('completed_items',{}))
        self.base=os.environ.get('SEB_GATEWAY_URL') or self.context.get('base_url','http://127.0.0.1:18765')
        self.token=self.context['token']
        self.artifacts=Path(self.context.get('output_dir','/workspace/client-artifacts'))
        self.artifacts.mkdir(parents=True,exist_ok=True)

    def request(self,path,data=None,timeout=None,operation_id=None,item_id=None,sample_id=None):
        timeout=timeout or self.context.get('client_timeout_seconds',650)
        payload=None if data is None else json.dumps(data).encode()
        headers={'x-api-key':self.token,'Content-Type':'application/json'}
        if operation_id:headers['x-seb-operation-id']=operation_id
        if item_id is not None:headers['x-seb-item-id']=str(item_id)
        if sample_id is not None:headers['x-seb-sample-id']=sample_id
        req=urllib.request.Request(self.base+path,data=payload,headers=headers)
        try:
            with urllib.request.urlopen(req,timeout=timeout) as r:
                return r.read(),dict(r.headers)
        except urllib.error.HTTPError as e:
            message=e.read().decode(errors='replace')
            if self.context.get('protocol_version')==1:
                try:payload=json.loads(message)
                except ValueError:payload={'error':{'type':'invalid_gateway_response'}}
                raise EvaluationError(e.code,payload,dict(e.headers)) from e
            raise RuntimeError(f'HTTP {e.code}: {message}') from e

    def budget(self):
        return json.loads(self.request('/budget')[0])

    def info(self):
        return json.loads(self.request('/research/info')[0])

    def feedback(self,job_ids):
        return json.loads(self.request('/research/feedback',{'job_ids':job_ids},timeout=7200)[0])

    def chat(self,prompt,*,model=None,max_tokens=None,system=None,messages=None,operation_id=None,item_id=None,sample_id=None):
        model=model or self.context.get('model')
        if not model:raise ValueError('Specify a model or use the evaluation context model')
        policy=self.context.get('evaluation_policy')
        if max_tokens is None:max_tokens=policy['default_output_tokens'] if policy else 2048
        if policy and (type(max_tokens) is not int or not policy['min_output_tokens']<=max_tokens<=policy['max_output_tokens']):
            raise ValueError('Output limit violates the frozen policy; no silent clamp')
        body={'model':model,'max_tokens':max_tokens,'messages':messages or [{'role':'user','content':prompt}]}
        if system:body['system']=system
        effort=self.context.get('efforts',{}).get(model)
        if effort:body['output_config']={'effort':effort}
        group=self.resume.get('item_budget_groups',{}).get(item_id,item_id)
        key=hashlib.sha256(json.dumps({'body':body,'group':group,'sample':sample_id},sort_keys=True,separators=(',',':')).encode()).hexdigest()
        if key in self.resume.get('replies',{}):return copy.deepcopy(self.resume['replies'][key])
        if item_id in self.completed_items:
            raise ValueError('Completed frozen item cannot issue another model call; reuse completed_items')
        operation_id=operation_id or uuid.uuid4().hex
        if not all(c.isalnum() or c in '_-' for c in operation_id) or not 1<=len(operation_id)<=128:
            raise ValueError('Invalid operation ID')
        (self.artifacts/(operation_id+'.request.json')).write_text(json.dumps(body))
        raw,headers=self.request('/anthropic/v1/messages',body,operation_id=operation_id,item_id=item_id,sample_id=sample_id)
        data=json.loads(raw);call_id=headers.get('x-seb-request-id')
        if not call_id:raise RuntimeError('Gateway did not supply an evidence ID')
        (self.artifacts/(call_id+'.response.json')).write_bytes(raw)
        return {'text':''.join(c.get('text','') for c in data.get('content',[]) if c.get('type')=='text'),
                'response':data,'evidence':{'kind':'llm','id':call_id},
                'operation_id':operation_id,'attempt_count':int(headers.get('x-seb-attempt-count',1)),
                'finish_reason':data.get('stop_reason')}

    def item(self,item_id,prompt,grader,**kwargs):
        """Run once through platform retry policy, then grade once; no answer retries.

        grader(text) returns a score in [0,1], or a dict with score, answer_status
        and an optional evidence list. Helper calls must use the same item/budget group.
        A grader API failure leaves the item incomplete without retrying its answer;
        other grader exceptions propagate as program defects, not wrong answers.
        """
        if item_id in self.completed_items:return copy.deepcopy(self.completed_items[item_id])
        try:
            reply=self.chat(prompt,item_id=item_id,**kwargs)
        except EvaluationError as error:
            execution=('infra_error' if error.category=='infra_error' else
                       'budget_exhausted' if error.category=='budget_exceeded' else 'not_run')
            return {'id':item_id,'score':None,'execution_status':execution,'answer_status':'not_applicable',
                    'evidence':error.evidence,'operation_id':error.operation_id,'error_category':error.category}
        try:
            graded=grader(reply['text']) if reply['text'].strip() else {'score':0,'answer_status':'missing'}
        except EvaluationError as error:
            execution=('infra_error' if error.category=='infra_error' else
                       'budget_exhausted' if error.category=='budget_exceeded' else 'not_run')
            return {'id':item_id,'score':None,'execution_status':execution,'answer_status':'not_applicable',
                    'evidence':[reply['evidence'],*error.evidence],'error_stage':'grading',
                    'answer_operation_id':reply['operation_id'],'operation_id':error.operation_id,
                    'error_category':error.category}
        if not isinstance(graded,dict):graded={'score':graded,'answer_status':'answered'}
        extra=graded.get('evidence',[])
        if not isinstance(extra,list):raise ValueError('Grader evidence must be a list')
        if graded.get('execution_status','completed')!='completed':
            raise ValueError('Return incomplete items explicitly; a grader result must be completed')
        return {**graded,'id':item_id,'execution_status':'completed','evidence':[reply['evidence'],*extra],
                'finish_reason':reply['finish_reason'],'operation_id':reply['operation_id'],
                'attempt_count':reply['attempt_count']}

    def submit(self,path,*,model=None,kind='suite',max_tokens=None,pilot=False,item_id=None,sample_id=None):
        body={'path':str(path),'model':model or self.context.get('model')}
        if sample_id is not None:body['sample_id']=sample_id
        if pilot:body['pilot']=True
        if max_tokens is not None:
            if kind!='agent':raise ValueError('max_tokens applies to agent tasks only')
            body['max_output_tokens']=max_tokens
        if kind=='agent':
            normalized=dict(body,path=str(path).removeprefix('/workspace/'))
            group=self.resume.get('item_budget_groups',{}).get(item_id,item_id)
            key=hashlib.sha256(json.dumps({'body':{'agent':normalized},'group':group,'sample':None},sort_keys=True,separators=(',',':')).encode()).hexdigest()
            if key in self.resume.get('agents',{}):return copy.deepcopy(self.resume['agents'][key])
            if item_id in self.completed_items:raise ValueError('Completed item cannot launch another agent')
        return json.loads(self.request('/research/'+('suites' if kind=='suite' else 'agents'),body,item_id=item_id)[0])

    def status(self,job_id):
        if job_id in self.resume.get('agent_results',{}):return copy.deepcopy(self.resume['agent_results'][job_id])
        return json.loads(self.request('/research/jobs/'+job_id)[0])

    def jobs(self):
        return json.loads(self.request('/research/jobs')[0])

    def cancel(self,job_id):
        return json.loads(self.request('/research/jobs/'+job_id+'/cancel',{})[0])

    def artifacts_list(self,job_id):
        return json.loads(self.request('/research/jobs/'+job_id+'/artifacts')[0])

    def artifact(self,job_id,relative,destination):
        from urllib.parse import quote
        raw,_=self.request('/research/jobs/'+job_id+'/artifacts/'+quote(relative,safe='/'))
        target=Path(destination);target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(raw)
        return str(target)

    def wait(self,job_id,*,timeout=1800):
        end=time.monotonic()+timeout
        while time.monotonic()<end:
            result=self.status(job_id)
            if result['status'] not in ('queued','running'):return result
            time.sleep(2)
        raise TimeoutError('Job still running; poll the same ID, do not resubmit: '+job_id)

    def agent(self,path,*,model=None,timeout=1800,max_tokens=None,item_id=None,sample_id=None):
        job=self.submit(path,model=model,kind='agent',max_tokens=max_tokens,item_id=item_id,sample_id=sample_id)
        result=self.wait(job['id'],timeout=timeout)
        return {'result':result,'evidence':{'kind':'agent','id':job['id']}}

    def suite(self,path,*,model,timeout=1800,sample_id=None):
        job=self.submit(path,model=model,kind='suite',sample_id=sample_id)
        return self.wait(job['id'],timeout=timeout)
